"""
Authentication Module

Implements JWT-based stateless authentication for agent identity verification.
Provides token generation, verification, and a decorator for middleware integration.
"""

from typing import Optional, Callable, Any
from datetime import datetime, timedelta
import jwt
import uuid
from functools import wraps


# In production, this should be loaded from a secure vault/environment
SECRET_KEY = "swarm-os-v12-secret-key-change-in-production"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30


class AuthenticationError(Exception):
    """Custom exception for authentication failures."""
    def __init__(self, message: str, code: str = "AUTH_FAILED"):
        self.message = message
        self.code = code
        super().__init__(self.message)


class AgentIdentity:
    """Represents a verified agent identity."""
    def __init__(self, agent_id: str, role: str, permissions: list):
        self.agent_id = agent_id
        self.role = role
        self.permissions = permissions
        self.authenticated_at = datetime.utcnow()

    def to_dict(self) -> dict:
        return {
            "agent_id": self.agent_id,
            "role": self.role,
            "permissions": self.permissions,
            "authenticated_at": self.authenticated_at.isoformat()
        }


class AuthManager:
    """
    Manages agent authentication and authorization.
    Uses JWT for stateless, scalable identity verification.
    """

    @staticmethod
    def register_agent(agent_id: str, role: str = "agent", permissions: Optional[list] = None) -> str:
        """
        Register a new agent and generate an identity token.

        Args:
            agent_id: Unique identifier for the agent
            role: Agent role (e.g., 'agent', 'admin', 'system')
            permissions: List of permission strings

        Returns:
            JWT token string
        """
        if not agent_id or not isinstance(agent_id, str):
            raise AuthenticationError("Invalid agent_id", "INVALID_ID")

        payload = {
            "agent_id": agent_id,
            "role": role,
            "permissions": permissions or [],
            "jti": str(uuid.uuid4()),  # Unique token ID
            "iat": datetime.utcnow(),
            "exp": datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
        }

        token = jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)
        return token

    @staticmethod
    def verify_token(token: str) -> AgentIdentity:
        """
        Verify a JWT token and return the agent identity.

        Args:
            token: JWT token string

        Returns:
            AgentIdentity object

        Raises:
            AuthenticationError: If token is invalid or expired
        """
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        except jwt.ExpiredSignatureError:
            raise AuthenticationError("Token has expired", "TOKEN_EXPIRED")
        except jwt.InvalidTokenError as e:
            raise AuthenticationError(f"Invalid token: {str(e)}", "INVALID_TOKEN")

        return AgentIdentity(
            agent_id=payload["agent_id"],
            role=payload["role"],
            permissions=payload["permissions"]
        )

    @staticmethod
    def refresh_token(token: str) -> str:
        """
        Refresh an existing token if it's still valid.

        Args:
            token: Current JWT token

        Returns:
            New JWT token with extended expiration
        """
        identity = AuthManager.verify_token(token)
        return AuthManager.register_agent(
            identity.agent_id,
            identity.role,
            identity.permissions
        )


def requires_auth(func: Callable) -> Callable:
    """
    Decorator to enforce authentication on agent functions.

    Usage:
        @requires_auth
        async def my_agent_function(token: str, *args, **kwargs):
            # Function implementation
            pass
    """
    @wraps(func)
    async def wrapper(token: str, *args, **kwargs):
        try:
            identity = AuthManager.verify_token(token)
            # Inject identity into function context
            kwargs['_identity'] = identity
            return await func(token, *args, **kwargs)
        except AuthenticationError as e:
            raise e
    return wrapper